import 'dart:convert';
import 'package:drift/drift.dart';
import '../../../domain/domain_enums.dart';
import '../../../domain/entities.dart' as domain;
import '../app_database.dart' as data;
extension AssignmentRowMapper on data.TaskAssignment { domain.TaskAssignment toTaskAssignmentDomain()=>domain.TaskAssignment(id:id,taskId:taskId,userId:userId,assignmentRole:AssignmentRole.fromCode(assignmentRole),assignmentStatus:AssignmentStatus.fromCode(assignmentStatus),isPrimary:isPrimary,assignedAt:assignedAt.toUtc(),contributionPercentage:contributionPercentage,createdAt:createdAt.toUtc(),updatedAt:updatedAt.toUtc()); }
extension AssignmentDomainMapper on domain.TaskAssignment { data.TaskAssignmentsCompanion toCompanion()=>data.TaskAssignmentsCompanion(id:Value(id),taskId:Value(taskId),userId:Value(userId),assignmentRole:Value(assignmentRole.code),assignmentStatus:Value(assignmentStatus.code),isPrimary:Value(isPrimary),assignedAt:Value(assignedAt.toUtc()),contributionPercentage:Value(contributionPercentage),createdAt:Value(createdAt.toUtc()),updatedAt:Value(updatedAt.toUtc())); }
extension ChecklistRowMapper on data.ChecklistItem { domain.ChecklistItem toChecklistItemDomain()=>domain.ChecklistItem(id:id,taskId:taskId,titleAr:titleAr,titleEn:titleEn,isMandatory:isMandatory,isCompleted:isCompleted); }
extension CommentRowMapper on data.TaskComment { domain.TaskComment toTaskCommentDomain()=>domain.TaskComment(id:id,taskId:taskId,authorId:authorId,body:body,createdAt:createdAt.toUtc(),mentionUserIds:_strings(mentionUserIdsJson),syncState:CommentSyncState.fromCode(syncState)); }
List<String> _strings(String raw){try{return (jsonDecode(raw) as List).whereType<String>().toList();}catch(_){return const[];}}
extension AttachmentRowMapper on data.TaskAttachment { domain.TaskAttachment toTaskAttachmentDomain()=>domain.TaskAttachment(id:id,taskId:taskId,fileName:fileName,fileType:fileType,sizeBytes:sizeBytes,category:AttachmentCategory.fromCode(attachmentCategory),uploadedBy:uploadedBy,createdAt:createdAt.toUtc()); }
extension BlockerRowMapper on data.TaskBlocker { domain.TaskBlocker toTaskBlockerDomain()=>domain.TaskBlocker(id:id,taskId:taskId,reportedBy:reportedBy,type:BlockerType.fromCode(blockerType),description:description,startedAt:startedAt.toUtc(),status:BlockerStatus.fromCode(status)); }
extension ExtensionRowMapper on data.DeadlineExtensionRequest { domain.DeadlineExtensionRequest toExtensionRequestDomain()=>domain.DeadlineExtensionRequest(id:id,taskId:taskId,requestedBy:requestedBy,currentDueDate:currentDueDate.toUtc(),requestedDueDate:requestedDueDate.toUtc(),reason:reason,status:ExtensionRequestStatus.fromCode(status)); }
extension ApprovalRowMapper on data.TaskApproval { domain.TaskApproval toTaskApprovalDomain()=>domain.TaskApproval(id:id,taskId:taskId,approverId:approverId,status:ApprovalStatus.fromCode(status),submittedAt:submittedAt.toUtc(),sequenceNumber:sequenceNumber); }
